// Generate the KTX2 fixture the C++ reader is tested against.
//
// Committed to the tree, and generated by the same writer the asset packer uses.
// That is the point: a fixture hand-assembled in a different way would prove the
// reader agrees with the test author's idea of the format rather than with the
// writer that actually produces the files.
//
// The content is a deterministic pattern, not a gradient and not a flat colour.
// A flat image decodes correctly under a surprising number of wrong strides, a
// channel swap and a layer swap; a per-channel pattern with a layer and position
// term breaks under all three. The C++ test recomputes the same pattern, so a
// transposed stride or a swapped channel shows up as a specific wrong texel
// rather than as "the texture looks a bit off".
//
// Regenerate with: node tools/assets/fixture.mjs

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { writeKtx2Array } from './ktx2.mjs';

const OUT = 'native/tests/fixtures/pattern.ktx2';

const WIDTH = 8;
const HEIGHT = 8;
const LAYERS = 3;

function patternByte(x, y, layer, channel) {
  return (x * 7 + y * 3 + layer * 11 + channel * 37 + ((x * y) ^ 0x5a)) & 0xff;
}

function levelFor(level) {
  const w = Math.max(1, WIDTH >> level);
  const h = Math.max(1, HEIGHT >> level);
  // KTX2 stores all layers of a level contiguously, layer 0 first.
  const buffer = Buffer.alloc(LAYERS * w * h * 4);
  for (let layer = 0; layer < LAYERS; layer++) {
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const base = ((layer * h + y) * w + x) * 4;
        for (let c = 0; c < 4; c++) {
          buffer[base + c] = patternByte(x, y, layer, c);
        }
      }
    }
  }
  return buffer;
}

// 8x8 halves to 4x4, 2x2, 1x1: four levels.
const mips = [0, 1, 2, 3].map(levelFor);

const file = writeKtx2Array({
  width: WIDTH,
  height: HEIGHT,
  layers: LAYERS,
  mips,
  srgb: true,
  zstdLevel: 9,
  kvd: {
    KTXmaterial: 'pattern',
    EMERGENTlicense: 'CC0',
  },
});

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, file);
process.stdout.write(
  `Wrote ${OUT} — ${file.length} bytes, ${WIDTH}x${HEIGHT}, ${LAYERS} layers, ${mips.length} mips\n`,
);
